dashboard.definition:
{
	"title": "Agentic Ops",
	"description": "Secure Networking drill-down dashboard for Agentic Ops.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$time_tok.earliest$",
						"latest": "$time_tok.latest$"
					}
				}
			},
			"ds.spl2": {
				"options": {
					"queryParameters": {
						"earliest": "$time_tok.earliest$",
						"latest": "$time_tok.latest$"
					}
				}
			}
		},
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#0f172a",
				"strokeColor": "rgba(148,163,184,0.22)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Agentic Ops",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/agentic-ops.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e2e8f0",
				"markdown": "# Agentic Ops\nTelemetry readiness, synthetic-path health, routing instability, and AI Defense signals."
			}
		},
		"viz_agentic_ai_defense": {
			"type": "splunk.singlevalueradial",
			"title": "AI Defense Block Rate",
			"dataSources": {
				"primary": "ds_agentic_ai_defense"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('block_pct') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('block_pct') | lastPoint() | rangeValue(lowerBetter)",
				"unit": "%"
			},
			"context": {
				"lowerBetter": [
					{
						"to": 20,
						"value": "#16a34a"
					},
					{
						"from": 20,
						"to": 50,
						"value": "#eab308"
					},
					{
						"from": 50,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_agentic_te_feed": {
			"type": "splunk.singlevalueradial",
			"title": "ThousandEyes Feed Age",
			"dataSources": {
				"primary": "ds_agentic_te_feed_health"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('age_minutes') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('age_minutes') | lastPoint() | rangeValue(staleness)",
				"unit": "min"
			},
			"context": {
				"staleness": [
					{
						"to": 30,
						"value": "#16a34a"
					},
					{
						"from": 30,
						"to": 90,
						"value": "#eab308"
					},
					{
						"from": 90,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_agentic_latency": {
			"type": "splunk.singlevalueradial",
			"title": "Avg Latency",
			"dataSources": {
				"primary": "ds_agentic_latency"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('avg_latency_ms') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('avg_latency_ms') | lastPoint() | rangeValue(latencyRange)",
				"unit": "ms"
			},
			"context": {
				"latencyRange": [
					{
						"to": 100,
						"value": "#16a34a"
					},
					{
						"from": 100,
						"to": 200,
						"value": "#eab308"
					},
					{
						"from": 200,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_agentic_loss": {
			"type": "splunk.singlevalueradial",
			"title": "Avg Packet Loss",
			"dataSources": {
				"primary": "ds_agentic_loss"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('avg_loss_pct') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('avg_loss_pct') | lastPoint() | rangeValue(lowerBetter)",
				"unit": "%"
			},
			"context": {
				"lowerBetter": [
					{
						"to": 1,
						"value": "#16a34a"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#eab308"
					},
					{
						"from": 5,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_agentic_loss_trend": {
			"type": "splunk.area",
			"title": "Network Loss Trend",
			"dataSources": {
				"primary": "ds_agentic_loss_trend"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#dc2626",
					"#f59e0b"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_agentic_bgp_changes": {
			"type": "splunk.area",
			"title": "BGP Path Changes",
			"dataSources": {
				"primary": "ds_agentic_bgp_changes"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#7c3aed",
					"#0ea5e9",
					"#f59e0b"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_agentic_test_health": {
			"type": "splunk.column",
			"title": "Healthy vs Degraded Tests",
			"dataSources": {
				"primary": "ds_agentic_test_health"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#dc2626"
				]
			}
		},
		"viz_agentic_http_availability": {
			"type": "splunk.bar",
			"title": "HTTP Availability by Test",
			"dataSources": {
				"primary": "ds_agentic_http_availability"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#f59e0b"
				]
			}
		},
		"viz_agentic_web_errors": {
			"type": "splunk.singlevalue",
			"title": "Web Transaction Errors",
			"dataSources": {
				"primary": "ds_agentic_web_errors"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('total_errors') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#dc2626"
			}
		},
		"viz_agentic_feed_matrix": {
			"type": "splunk.table",
			"title": "Telemetry Feed Health Matrix",
			"dataSources": {
				"primary": "ds_agentic_feed_matrix"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 25,
				"fontSize": "small",
				"showInternalFields": false
			}
		}
	},
	"dataSources": {
		"ds_agentic_ai_defense": {
			"name": "Security - GenAI Protection - Cisco AI Defense Block Rate",
			"options": {
				"query": "`index_security` sourcetype=\"cisco:ai:defense\"\n| stats count(eval(event_action=\"Block\")) as blocked count as total\n| eval block_pct=if(total>0, round(100*blocked/total,1), 0)\n| fields block_pct blocked total",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_agentic_te_feed_health": {
			"name": "Feed Monitor - ThousandEyes - Stream Staleness (Signal Rail KPI)",
			"options": {
				"query": "| makeresults\n| eval count_24h=0, last_ts=0\n| append [| tstats count as count_24h latest(_time) as last_ts WHERE `index_thousandeyes` AND sourcetype=\"cisco:thousandeyes:metric\"]\n| stats sum(count_24h) as count_24h max(last_ts) as last_ts\n| eval age_minutes=if(last_ts>0, round((now()-last_ts)/60, 0), 9999)\n| eval readiness=case(count_24h=0 OR last_ts=0,\"NOT ONBOARDED - configure ThousandEyes streaming TA\", age_minutes<=30,\"Active - last event \".tostring(age_minutes).\" min ago\", age_minutes<=90,\"WARNING - stale \".tostring(age_minutes).\" min - verify HEC endpoint and OAuth token\", 1==1,\"CRITICAL - STALE \".tostring(age_minutes).\" min - check OAuth2 token expiry in TE portal\")\n| eval last_seen=if(last_ts>0, strftime(last_ts,\"%Y-%m-%d %H:%M:%S\"), \"Never\")\n| fields count_24h age_minutes readiness last_seen",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_agentic_feed_matrix": {
			"name": "Feed Monitor - ALL Feeds - Consolidated Health Matrix",
			"options": {
				"query": "| tstats count as count_24h latest(_time) as last_ts WHERE (`index_catalyst` OR `index_cybervision` OR `index_dc` OR `index_dhcp` OR `index_duo` OR `index_f5` OR `index_firewall` OR `index_identity` OR `index_meraki` OR `index_network` OR `index_nvm` OR `index_sdwan` OR `index_security` OR `index_spaces` OR `index_thousandeyes` OR `index_ucs` OR `index_windows` OR `index_zeek`) AND (sourcetype=\"cisco:thousandeyes:metric\" OR sourcetype=\"cisco:ftd\" OR sourcetype=\"cisco:ftd:syslog\" OR sourcetype=\"cisco:ftd:adv:conn\" OR sourcetype=\"cisco:ftd:connection\" OR sourcetype=\"cisco:sfw:estreamer\" OR sourcetype=\"cisco:dnac:devicehealth\" OR sourcetype=\"cisco:catalyst:devicehealth\" OR sourcetype=\"cisco:sdwan:tunnelhealth\" OR sourcetype=\"cisco:sdwan:linkhealth\" OR sourcetype=\"cisco:ise:syslog\" OR sourcetype=\"cisco:spaces:firehose\" OR sourcetype=\"cisco:ios\" OR sourcetype=\"cisco:duo:authentication\" OR sourcetype=\"cisco:duo:authentication_v2\" OR sourcetype=\"meraki:devicelosslatency\" OR sourcetype=\"zeek:conn\" OR sourcetype=\"cisco:dc:aci:health\" OR sourcetype=\"cisco:dc:nd:anomalies\") BY sourcetype\n| eval feed=case(sourcetype=\"cisco:thousandeyes:metric\",\"ThousandEyes Stream\", sourcetype=\"cisco:ftd\" OR sourcetype=\"cisco:ftd:syslog\",\"FTD Firewall Syslog\", sourcetype=\"cisco:ftd:adv:conn\" OR sourcetype=\"cisco:ftd:connection\",\"FTD Advanced Conn JSON\", sourcetype=\"cisco:sfw:estreamer\",\"FMC eStreamer IPS\", sourcetype=\"cisco:dnac:devicehealth\" OR sourcetype=\"cisco:catalyst:devicehealth\",\"Catalyst Center API\", sourcetype=\"cisco:sdwan:tunnelhealth\" OR sourcetype=\"cisco:sdwan:linkhealth\",\"SD-WAN vManage\", sourcetype=\"cisco:ise:syslog\",\"ISE RADIUS Syslog\", sourcetype=\"cisco:spaces:firehose\",\"Cisco Spaces Firehose\", sourcetype=\"cisco:ios\",\"IOS/IOS-XE Syslog\", sourcetype=\"cisco:duo:authentication\" OR sourcetype=\"cisco:duo:authentication_v2\",\"Duo Admin API\", sourcetype=\"meraki:devicelosslatency\",\"Meraki Dashboard API\", sourcetype=\"zeek:conn\",\"Zeek NDR\", sourcetype=\"cisco:dc:aci:health\" OR sourcetype=\"cisco:dc:nd:anomalies\",\"ACI / Nexus Dashboard\", 1==1, sourcetype)\n| eval stale_warn=case(match(feed,\"ThousandEyes\"),30, match(feed,\"FTD\"),30, match(feed,\"eStreamer\"),60, match(feed,\"Catalyst\"),60, match(feed,\"SD-WAN\"),60, match(feed,\"ISE\"),30, match(feed,\"Spaces\"),90, match(feed,\"IOS\"),120, match(feed,\"Duo\"),120, match(feed,\"Meraki\"),60, match(feed,\"Zeek\"),30, match(feed,\"ACI\"),60, 1==1,60)\n| eval stale_crit=stale_warn*3\n| eval age_minutes=round((now()-last_ts)/60, 0)\n| eval status=case(age_minutes<=stale_warn,\"Active\", age_minutes<=stale_crit,\"WARNING\", 1==1,\"CRITICAL\")\n| stats sum(count_24h) as count_24h max(last_ts) as last_ts min(age_minutes) as age_minutes first(status) as status by feed\n| eval last_seen=strftime(last_ts,\"%Y-%m-%d %H:%M:%S\")\n| eval sort_order=case(status=\"CRITICAL\",1, status=\"WARNING\",2, 1==1,3)\n| sort sort_order feed\n| rename feed as \"Feed\" count_24h as \"Events (24h)\" age_minutes as \"Age (min)\" last_seen as \"Last Event\" status as \"Status\"\n| fields \"Feed\" \"Events (24h)\" \"Age (min)\" \"Last Event\" \"Status\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_base_agentic_te": {
			"name": "Secure Networking base - ThousandEyes metrics",
			"options": {
				"query": "`index_thousandeyes` sourcetype=\"cisco:thousandeyes:metric\"\n| eval test_name=coalesce('thousandeyes.test.name',test_name,\"Unknown\"), agent=coalesce('thousandeyes.source.agent.location',agent_location,\"Unknown\")",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_agentic_test_health": {
			"name": "Secure Networking chain - ThousandEyes test health",
			"options": {
				"extend": "ds_base_agentic_te",
				"query": "| eval degraded=case(metric_name=\"network.loss\" AND value>5,1, metric_name=\"http.server.request.availability\" AND value<95,1, 1==1,0)\n| stats dc(test_name) as total_tests, dc(eval(if(degraded=1,test_name,null()))) as degraded_tests\n| eval healthy_tests=total_tests-degraded_tests\n| eval label=\"ThousandEyes Test Health\"\n| fields label healthy_tests degraded_tests"
			},
			"type": "ds.chain"
		},
		"ds_agentic_latency": {
			"name": "Secure Networking chain - ThousandEyes average latency",
			"options": {
				"extend": "ds_base_agentic_te",
				"query": "| search metric_name=\"network.latency\"\n| stats avg(value) as avg_latency_ms, max(value) as max_latency_ms, perc95(value) as p95_latency_ms, dc(test_name) as test_count\n| eval avg_latency_ms=round(avg_latency_ms,2), max_latency_ms=round(max_latency_ms,2), p95_latency_ms=round(p95_latency_ms,2)\n| eval label=\"Avg Network Latency (ms)\"\n| fields label avg_latency_ms max_latency_ms p95_latency_ms test_count"
			},
			"type": "ds.chain"
		},
		"ds_agentic_loss": {
			"name": "Secure Networking chain - ThousandEyes packet loss",
			"options": {
				"extend": "ds_base_agentic_te",
				"query": "| search metric_name=\"network.loss\"\n| stats avg(value) as avg_loss_pct, max(value) as max_loss_pct, dc(test_name) as test_count\n| eval avg_loss_pct=round(avg_loss_pct,2), max_loss_pct=round(max_loss_pct,2)\n| eval label=\"Avg Packet Loss %\"\n| fields label avg_loss_pct max_loss_pct test_count"
			},
			"type": "ds.chain"
		},
		"ds_agentic_web_errors": {
			"name": "Secure Networking chain - ThousandEyes web errors",
			"options": {
				"extend": "ds_base_agentic_te",
				"query": "| search metric_name=\"web.transaction.errors.count\"\n| stats sum(value) as total_errors, dc(test_name) as affected_tests\n| eval label=\"Web Transaction Errors\"\n| fields label total_errors affected_tests"
			},
			"type": "ds.chain"
		},
		"ds_agentic_loss_trend": {
			"name": "Secure Networking chain - ThousandEyes loss trend",
			"options": {
				"extend": "ds_base_agentic_te",
				"query": "| search metric_name=\"network.loss\"\n| timechart span=1h avg(value) as avg_loss_pct, max(value) as max_loss_pct"
			},
			"type": "ds.chain"
		},
		"ds_agentic_bgp_changes": {
			"name": "Secure Networking chain - ThousandEyes BGP path changes",
			"options": {
				"extend": "ds_base_agentic_te",
				"query": "| search metric_name=\"bgp.path.changes\"\n| timechart span=1h sum(value) as path_changes by test_name"
			},
			"type": "ds.chain"
		},
		"ds_agentic_http_availability": {
			"name": "Secure Networking chain - ThousandEyes HTTP availability",
			"options": {
				"extend": "ds_base_agentic_te",
				"query": "| search metric_name=\"http.server.request.availability\"\n| stats avg(value) as avg_availability, min(value) as min_availability by test_name\n| eval avg_availability=round(avg_availability,2), min_availability=round(min_availability,2)\n| sort avg_availability\n| head 15\n| rename test_name as \"Test Name\", avg_availability as \"Avg Availability %\", min_availability as \"Min Availability %\"\n| table \"Test Name\", \"Avg Availability %\", \"Min Availability %\""
			},
			"type": "ds.chain"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#020617",
					"display": "auto-scale",
					"height": 1490,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 9,
							"w": 72,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 120,
							"y": 0,
							"w": 1300,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_ai_defense",
						"position": {
							"x": 20,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_te_feed",
						"position": {
							"x": 375,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_latency",
						"position": {
							"x": 730,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_loss",
						"position": {
							"x": 1085,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_loss_trend",
						"position": {
							"x": 20,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_bgp_changes",
						"position": {
							"x": 730,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_test_health",
						"position": {
							"x": 20,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_http_availability",
						"position": {
							"x": 730,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_web_errors",
						"position": {
							"x": 20,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_agentic_feed_matrix",
						"position": {
							"x": 730,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": true,
		"hideExport": false
	}
}
